def strip_t(m):
    m = json.loads(json.dumps(m))
    for P in m['stages']:
        P.pop('seconds', None)
        if 'log' in P: P['log'].pop('sha256', None)
    return m
def diffpaths(a, b, p=''):
    if isinstance(a, dict) and isinstance(b, dict):
        out = []
        for k in sorted(set(a) | set(b)): out += diffpaths(a.get(k), b.get(k), f'{p}/{k}')
        return out
    if isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
        out = []
        for i, (x, y) in enumerate(zip(a, b)): out += diffpaths(x, y, f'{p}/{i}')
        return out
    return [] if a == b else [p]
